// src/lib/mcp/tools/list-products.ts
var list_products_default = defineTool({
  name: "list_products",
  title: "List INSULFILM products",
  description: "List every INSULFILM\u2122 product available on the site (slug, commercial name, page URL, and category).",
  inputSchema: {
    lang: z.enum(["pt", "en", "es"]).default("pt").describe("Language for the returned category label (pt, en, or es).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ lang }) => {
    const items = Object.entries(PDP_PRODUCTS).map(([slug, p]) => ({
      slug,
      name: p.name,
      url: p.url,
      category: p.category?.[lang] ?? null
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { products: items }
    };
  }
});

// src/lib/mcp/tools/get-product.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.22.2";
import { z as z2 } from "npm:zod@^3.23.8";
var get_product_default = defineTool2({
  name: "get_product",
  title: "Get INSULFILM product details",
  description: "Return full public details for one INSULFILM\u2122 product: description, technical properties, category, rating, and page URL.",
  inputSchema: {
    slug: z2.string().min(1).describe("Product slug, e.g. 'matrix', 'raystart', 'carbon'."),
    lang: z2.enum(["pt", "en", "es"]).default("pt").describe("Language for text fields.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug, lang }) => {
    const p = PDP_PRODUCTS[slug];
    if (!p) {
      return {
        content: [{ type: "text", text: `No product found for slug '${slug}'.` }],
        isError: true
      };
    }
    const data = {
      slug,
      name: p.name,
      description: p.description[lang],
      url: p.url,
      category: p.category?.[lang] ?? null,
      properties: p.properties.map((prop) => ({
        name: prop.name[lang],
        value: prop.value[lang]
      })),
      rating: p.rating ?? null
    };
    return {
      content: [{ type: "text", text: JSON.stringify(data, null, 2) }],
      structuredContent: { product: data }
    };
  }
});

