var pickFAQs = (faqs, lang) => faqs.map((f) => ({ q: f.q[lang], a: f.a[lang] }));
var getPDPFaqs = (slug, lang) => {
  const meta = PDP_META[slug];
  if (!meta) return null;
  return pickFAQs(meta.faqs, lang);
};

// src/lib/mcp/tools/get-faqs.ts
var get_faqs_default = defineTool3({
  name: "get_faqs",
  title: "Get product FAQs",
  description: "Return the public FAQ list (question/answer pairs) for one INSULFILM\u2122 product page.",
  inputSchema: {
    slug: z3.string().min(1).describe("Product slug, e.g. 'matrix', 'raystart', 'carbon'."),
    lang: z3.enum(["pt", "en", "es"]).default("pt").describe("Language for the FAQs.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug, lang }) => {
    const faqs = getPDPFaqs(slug, lang);
    if (!faqs) {
      return {
        content: [{ type: "text", text: `No FAQs found for slug '${slug}'.` }],
        isError: true
      };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(faqs, null, 2) }],
      structuredContent: { faqs }
    };
  }
});

// src/lib/mcp/index.ts
var mcp_default = defineMcp({
  name: "insulfilm-mcp",
  title: "INSULFILM\u2122 Site MCP",
  version: "0.1.0",
  instructions: "Public tools for the INSULFILM\u2122 site. Use `list_products` to discover products, `get_product` for full specs of a product by slug, and `get_faqs` to fetch the public FAQ for a product. All content is public and available in Portuguese (pt), English (en), and Spanish (es).",
  tools: [list_products_default, get_product_default, get_faqs_default]
});

// lovable-mcp-supabase-entry.ts
import { createSupabaseHandler } from "npm:@lovable.dev/mcp-js@0.22.2/stacks/supabase";
Deno.serve(createSupabaseHandler(mcp_default, { functionName: "mcp" }));
